def edit(html):
    html=re.sub(r'<p\b[^>]*>Referencia:[\s\S]*?</p>', '', html)
    for before,after in REPLACEMENTS.items(): html=html.replace(before,after)
    html = re.sub(r'<div class="notas-visuales"><h[2-6]>Observaciones sobre el procedimiento</h[2-6]></div>', "", html)
    return html
